_attachment', array($this, 'ajax_sync_single_ucloud') ); } public function get_attachments_list() { if (!current_user_can($this->options->authorization)) return; $mode = $_REQUEST['mode']; $paged = $_REQUEST['paged']; switch ($mode) { case 'fast': $args = array( 'post_type' => 'attachment', 'meta_key' => '_sync_ucloud', 'meta_value' => 1, 'meta_compare' => 'NOT EXISTS', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; case 'smart': $args = array( 'post_type' => 'attachment', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; } $attachments = get_posts($args); if (!empty($attachments)) { switch ($mode) { case 'fast': $success_message = sprintf(_n('%d no synced attachment found, syncing...', '%d no synced attachments found, syncing...', count($attachments), $this->text_domain), number_format_i18n(count($attachments))); break; case 'smart': $success_message = sprintf(_n('%d attachment found, scanning...', '%d attachments found, scanning...', count($attachments), $this->text_domain), number_format_i18n(count($attachments))); break; } $array = array(); foreach ($attachments as $attachment) $array[] = $attachment->ID; $results = array( 'success' => 1, 'msg' => $success_message, 'attachments' => $array ); } else { $failed_message = __('Congratulations, seems like all attachments had already synced.', $this->text_domain); $results = array( 'success' => 0, 'msg' => $failed_message ); } echo json_encode($results); exit; } public function test_access_ucloud() { global $UCLOUD_PROXY_SUFFIX, $UCLOUD_PUBLIC_KEY, $UCLOUD_PRIVATE_KEY; $this->bucket = isset($_POST['bucket']) ? $_POST['bucket'] : $this->bucket; $UCLOUD_PROXY_SUFFIX = isset($_POST['proxy_suffix']) ? $_POST['proxy_suffix'] : $this->proxy_suffix; $UCLOUD_PUBLIC_KEY = isset($_POST['public_key']) ? $_POST['public_key'] : $this->public_key; $UCLOUD_PRIVATE_KEY = isset($_POST['private_key']) ? $_POST['private_key'] : $this->private_key; $key = "test.txt"; $file = QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY