t = preg_replace('/(https?:)?\/\/'.$home_url['host'].'/i', $this->protocol . $this->host, $resource); $buffer = str_replace( $resource, $replacement, $buffer ); } } return $buffer; } public function sync_file() { if (!isset($_POST['file'])) echo json_encode(array( 'error' => 1, 'msg' => __('File path can not be empty.', $this->text_domain) )); $file = $_POST['file']; $wp_upload_dir = wp_upload_dir(); $basedir = str_replace('/wp-content/uploads', '', $wp_upload_dir['basedir']); $destination_path = $file; $source_path = $basedir . $file; if (file_exists($source_path)) { $this->upload($destination_path, $source_path); echo json_encode(array( 'error' => 0, 'msg' => sprintf(__('File has been synchronized: %s.', $this->text_domain), $source_path) )); } else { echo json_encode(array( 'error' => 1, 'msg' => sprintf(__('File is not exists: %s.', $this->text_domain), $source_path) )); } } public function optimize_action() { add_filter( 'image_send_to_editor',array($this, 'image_send_to_editor'), 10, 8 ); add_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); add_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); add_action( 'delete_attachment', array($this, 'delete_attachment') ); add_action( 'qqworld-auto-save-images-after-sync-oss-'.$this->slug, array($this, 'do_delete_attachment_after_synced') ); add_filter( 'wp_calculate_image_srcset', array($this, 'wp_calculate_image_srcset'), 10, 5); } public function wp_calculate_image_srcset($sources, $size_array, $image_src, $image_meta, $attachment_id) { $is_synced = get_post_meta($attachment_id, '_sync_ucloud', true); if ($is_synced) { foreach ($sources as $id => $source) { $sources[$id]['url'] = $this->parse_url($sources[$id]['url'], $this->ucloud); } } return $sources; } public function delete_attachment($post_id) { if ($this->sync_delete == 'yes') { $metadata = wp_get_attachment_metadata( $post_id ); $sizes = $this->parse_metadata($post_id, $metadata, $this->ucloud); if (!empty($sizes)) foreach ($sizes as $size) { if ($this->is_file_exists($size['destination_path'])) $this->delete($size['destination_path']); } } } public function do_delete_attachment_after_synced($res) { $attachment_id = $res['id']; $is_synced = get_post_meta($attachment_id, '_sync_ucloud', true); if ($this->delete_attachment_after_synced == 'yes' && $is_synced == 1) { wp_schedule_single_event( time() + 10, 'cron_delete_attachment_after_synced', array($attachment_id) ); } } public function wp_get_attachment_url($url, $post_id) { if ( get_post_meta($post_id, '_sync_ucloud', true) ) $url = $this->parse_url($url, $this->ucloud); return $url; } public function image_send_to_editor($html, $id, $caption, $title, $align, $url, $size, $alt) { if (get_post_meta($id, '_sync_ucloud', true)) { remove_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); remove_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); $original_image_url = wp_get_attachment_image_src($id, 'full'); add_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); add_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); $synced_image_url = wp_get_attachment_image_src($id, 'full'); $html = str_replace($original_image_url[0], $synced_image_url[0], $html); } return $html; } public function image_downsize($downsize, $id, $size) { if (get_post_meta($id, '_sync_ucloud', true)) { $metadata = wp_get_attachment_metadata( $id ); $sizes = $this->parse_metadata($id, $metadata, $this->ucloud); $image_sizes = !empty($metadata['sizes']) ? $metadata['sizes'] : null; if ( !is_array($size) ) { if (!isset($sizes[$size])) return null; $width = isset($sizes[$size]['width']) ? $sizes[$size]['width'] : ''; $height = isset($sizes[$size]['height']) ? $sizes[$size]['height'] : ''; return $size == 'full' ? array($sizes[$size]['src'], $width, $height) : array($sizes[$size]['src'], $width, $height, true); } else { if ( $intermediate = image_get_intermediate_size($id, $size) ) { $width = $intermediate['width']; $height = $intermediate['height']; foreach ($image_sizes as $size_name => $size) { if ($width < $size['width'] && $height < $size['height']) { break; } } return $size_name == 'full' ? array($sizes[$size_name]['src'], $width, $height) : array($sizes[$size_name]['src'], $width, $height, true); } else if (isset($sizes['full'])) { return array($sizes['full']['src'], $size[0], $size[1]); } } } } public function manage_media_columns( $cols ) { $cols["ucloud_upload"] = __("UCloud", $this->text_domain); return $cols; } public function sync_single_ucloud($attachment_id=null) { if ( !current_user_can( $this->options->authorization ) ) return; if (!$attachment_id) { $attachment_id = $_POST['attachment_id']; } $results = $this->sync($attachment_id); echo json_encode($results); exit; } public function ajax_sync_single_ucloud() { if ( !current_user_can( $this->options->authorization ) ) return; $mode = 'fast'; $attachment_id = $_POST['attachment_id']; $this->sync($attachment_id, null, null, $mode); $results = array( 'msg' => __('Synced', $this->text_domain) ); echo json_encode($results); exit; } public function manage_media_custom_column( $column_name, $id ) { switch ($column_name) { case 'ucloud_upload': $synced = get_post_meta($id, '_sync_ucloud', true); if ($synced) { echo '<input type="button" attachment-id="'.$id.'" class="button" name="sync-ucloud-again" value="'.__('Sync Again', $this->text_domain).'">'; } else { echo '<input type="button" attachment-id="'.$id.'" class="button button-primary" name="sync-ucloud-now" value="'.__('Sync Now', $this->text_domain).'">'; } break; } } public function exclude_domain($exclude_domain) { if (!is_array($exclude_domain)) $exclude_domain = array(); if (!empty($this->host)) $exclude_domain[] = $this->host; return $exclude_domain; } public function sync_ucloud($metadata, $attachment_id, $optimize_url) { $this->sync($attachment_id, null, $metadata); } public function sync($attachment_id, $attachment=null, $metadata=null, $mode='fast') { if ($attachment) { $type = is_object($attachment) ? $attachment->post_mime_type : $attachment['post_mime_type']; } else { $attachment = get_post($attachment_id); $type = $attachment->post_mime_type; } $metadata = $metadata ? $metadata : wp_get_attachment_metadata( $attachment_id ); $results = array( 'type' => $type, 'metadata' => $metadata, 'attachment' => $attachment ); $sizes = $this->parse_metadata($attachment_id, $metadata, $this->ucloud); if (!defined('CDN_UPLOADED'.$attachment_id)) { if (in_array($type, $this->allowed_image_types)) { if (!empty($sizes)) foreach ($sizes as $label => $size) { $destination_path = $size['destination_path']; $source_path = $size['source_path']; $allow = false; switch ($mode) { case 'fast': if (file_exists($source_path)) $allow = true; break; case 'smart': $result = $this->is_file_exists($destination_path); if ($result->status == 404) $allow = true; break; } if ($allow) { $this->upload($destination_path, $source_path); } else unset($sizes[$label]); } $results['sizes'] = $sizes; $this->auto_replace($attachment_id, $type, $sizes); } else { if (isset($sizes['file'])) { $destination_path = $sizes['file']['destination_path']; $source_path = $sizes['file']['source_path']; if (file_exists($source_path)) { $this->upload($destination_path, $source_path); $this->auto_replace($attachment_id, $type, $source_path); } } } $results['success'] = 1; update_post_meta($attachment_id, '_sync_ucloud', 1); define('CDN_UPLOADED'.$attachment_id, 1); return $results; } } public function parse_url($url, $optimize_url) { $protocol = $optimize_url['protocol']; $host = $optimize_url['host']; $folder = $optimize_url['folder']; $url = preg_match('/uploads(.*?)$/i', $url, $match); $url = $protocol . $host . $folder . $match[1]; return $url; } public function parse_filepath($file, $optimize_url) { $protocol = $optimize_url['protocol']; $host = $optimize_url['host']; $folder = $optimize_url['folder']; $file_path = preg_match('/uploads(.*?)$/i', $file, $match); if ($file_path) { return array( 'icon' => site_url('/wp-includes/images/media/document.png'), 'src' => $protocol . $host . $folder . $match[1], 'destination_path' => $folder . $match[1], 'source_path' => $file, ); } else return null; } public function parse_metadata($attachment_id, $metadata, $optimize_url) { $dirs = wp_upload_dir(); $path = $dirs['path']; $sizes = array(); if (isset($metadata['file'])) { $full_file = $metadata['file']; $subpath = explode('/', $full_file); array_pop($subpath); $folder_path = implode('/', $subpath); $protocol = $optimize_url['protocol']; $host = $optimize_url['host']; $folder = $optimize_url['folder']; $folder = preg_replace('/^\//', '', $folder); $folder = $folder ? $folder . '/' : ''; $subfolder = $folder . $folder_path; $dir = $dirs['path'] . DIRECTORY_SEPARATOR; $sizes['full'] = array( 'src' => $protocol . $host . '/' . $folder . $full_file, 'destination_path' => $folder . $full_file, 'source_path' => $dirs['basedir'] . DIRECTORY_SEPARATOR . $metadata['file'], 'width' => $metadata['width'], 'height' => $metadata['height'] ); if (!empty($metadata['sizes'])) foreach ($metadata['sizes'] as $label => $size) { $sizes[$label] = array( 'src' => $protocol . $host . '/' . $subfolder . '/' . $size['file'], 'destination_path' => $subfolder . '/' . $size['file'], 'source_path' => $dirs['basedir'] . '/' . $folder_path . '/' . $size['file'], 'width' => $size['width'], 'height' => $size['height'] ); } } else { $file = get_attached_file($attachment_id); $result = $this->parse_filepath($file, $this->ucloud); if (!empty($result)) { $destination_path = $result['destination_path']; $source_path = $result['source_path']; $sizes['file'] = array( 'destination_path' => $destination_path, 'source_path' => $source_path ); $sizes['file'] = $result; } }; return $sizes; } public function auto_replace($attachment_id, $type, $args=null) { if ($this->auto_replace != 'yes') return; global $wpdb; remove_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); remove_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); $metadata = wp_get_attachment_metadata( $attachment_id ); $queues = array(); if (in_array($type, $this->allowed_image_types)) { $sizes = $this->parse_metadata($attachment_id, $metadata, $this->ucloud); if (!empty($sizes)) foreach ($sizes as $name => $size) { $queues[$name] = array(); $original_url = wp_get_attachment_image_src($attachment_id, $name); $queues[$name]['source_url'] = $original_url[0]; $queues[$name]['destination_url'] = $size['src']; } } else { $attachment_url = wp_get_attachment_url($attachment_id); $queues['file'] = array( 'source_url' => $attachment_url, 'destination_url' => $this->parse_url($attachment_url, $this->ucloud) ); } $post_types = get_post_types( '', 'names' ); unset($post_types['attachment']); unset($post_types['nav_menu_item']); if (!empty($queues)) foreach ($queues as $queue) { $source_url = $queue['source_url']; $destination_url = $queue['destination_url']; if (!empty($source_url) && !empty($destination_url)) { $sql = "UPDATE `{$wpdb->posts}` SET `post_content` = REPLACE(`post_content`, '{$source_url}', '{$destination_url}')"; $wpdb->query($sql); if ($this->options->special_custom_fields_enabled == 'yes') { $post_metas = $wpdb->get_results("SELECT * FROM `{$wpdb->postmeta}` WHERE `meta_value` LIKE '%{$source_url}%'", ARRAY_A); if (!empty($post_metas)) foreach ($post_metas as $post_meta) { $post_id = $post_meta['post_id']; $meta_key = $post_meta['meta_key']; $key = null; if (!empty($this->options->special_custom_fields)) foreach ($this->options->special_custom_fields as $key => $field) { if ($field['field'] == $meta_key) { $field = $this->options->special_custom_fields[$key]; $field_type = $field['type']; switch ($field_type) { case 'string': $value = $destination_url; break; case 'array': $value = get_post_meta($post_id, $meta_key, true); $array_key = $field['array-key']; $array = preg_replace('/^\[/i', '', $array_key); $array = preg_replace('/\]$/i', '', $array); $array = explode('][', $array); $codeStr = '$value'; foreach ($array as $key) { $codeStr .= '["'.$key.'"]'; } $codeStr .= ' = "' . $destination_url . '";'; eval($codeStr); break; } update_post_meta($post_id, $meta_key, $value); } } } } } } add_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); add_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); } public function includes() { if (!function_exists('UCloud_PutFile')) { define('UCLOUD_PROXY_SUFFIX', $this->proxy_suffix); define('UCLOUD_PUBLIC_KEY', $this->public_key); define('UCLOUD_PRIVATE_KEY', $this->private_key); require_once QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY_SEPARATOR . 'ucloud_sdk' . DIRECTORY_SEPARATOR . 'proxy.php'; } } public function add_media_library_mode($modes) { $modes['ucloud'] = __('Use UCloud Storage Service', $this->text_domain); return $modes; } public function add_media_library_form($optimize_mode) { ?>
