 } public function is_file_exists($dst) { $url = UCloud_MakePublicUrl($this->bucket, $dst); try { $url = urldecode($this->protocol . $url); $headers = get_headers($url, 1); return strstr($headers[0], '200') !== false; } catch (Exception $e) { return false; } } public function upload($dst, $src) { set_time_limit(3600); list($data, $err) = UCloud_PutFile($this->bucket, $dst, $src); if ($err) { return false; } return true; } public function delete($path) { list($data, $err) = UCloud_Delete($this->bucket, $path); if ($err) { return false; } return true; } } new ucloud;